    pawn='P' if by==0 else 'p'
    if 0<=rr<8:
        for ff in (f-1,f+1):
            if 0<=ff<8 and b[rr*8+ff]==pawn:return True
    knight='N' if by==0 else 'n'
    for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
        x,y=r+dr,f+df
        if 0<=x<8 and 0<=y<8 and b[x*8+y]==knight:return True
    king='K' if by==0 else 'k'
    for dr in (-1,0,1):
        for df in (-1,0,1):
            if dr or df:
                x,y=r+dr,f+df
                if 0<=x<8 and 0<=y<8 and b[x*8+y]==king:return True
    for dr,df,chars in ((1,0,'rq'),(-1,0,'rq'),(0,1,'rq'),(0,-1,'rq'),(1,1,'bq'),(1,-1,'bq'),(-1,1,'bq'),(-1,-1,'bq')):
        x,y=r+dr,f+df
        while 0<=x<8 and 0<=y<8:
            z=b[x*8+y]
            if z!='.':
                if z.isupper()==(by==0) and z.lower() in chars:return True
                break
            x+=dr;y+=df
    return False

def attacked(p,sq,by):return attacked_board(p.b,sq,by)

def king_square(p,side):
    k='K' if side==0 else 'k'
    for i,x in enumerate(p.b):
        if x==k:return i
    return -1

def effective_ep(p):
    ep=p.ep
    if ep<0:return -1
    d=8 if p.side==0 else -8
    src=ep-d
    victim=ep-d
    if not 0<=src<64 or not 0<=victim<64:return -1
    if p.b[victim] != ('p' if p.side==0 else 'P'):return -1
    for a in (src-1,src+1):
        if not 0<=a<64 or a//8!=src//8:continue
        if p.b[a] != ('P' if p.side==0 else 'p'):continue
        b=p.b[:]
        b[a]='.';b[victim]='.';b[ep]=('P' if p.side==0 else 'p')
        k=next((i for i,x in enumerate(b) if x==('K' if p.side==0 else 'k')),-1)
        if k>=0 and not attacked_board(b,k,p.side^1):return ep
    return -1

def position_key(p):return (tuple(p.b),p.side,p.cast,effective_ep(p))

def enc(a,z,pr=0,fl=0):return a|(z<<6)|(pr<<12)|(fl<<16)

def notation(m):
    a=m&63;z=(m>>6)&63;pr=(m>>12)&15
