def unmake(p,d):
    n=p.rep_counts.get(d.new_key,0)
    if n<=1:p.rep_counts.pop(d.new_key,None)
    else:p.rep_counts[d.new_key]=n-1
    if p.rep_stack:p.rep_stack.pop()
    for s,old in reversed(d.changes):p.b[s]=old
    p.side=d.side;p.cast=d.cast;p.ep=d.ep;p.half=d.half;p.full=d.full

def legal(p,captures=False,poll=None):
    out=[];side=p.side
    for m in pseudo(p,captures,poll):
        if poll:poll()
        z=(m>>6)&63
        if p.b[z].lower()=='k':continue
        d=make(p,m)
        try:
            k=king_square(p,side)
            if k>=0 and not attacked(p,k,side^1):out.append(m)
        finally:unmake(p,d)
    return out

class Engine:
    def __init__(self):
        self.pos=Position.start();self.tt={};self.history={};self.killers={};self.nodes=0;self.deadline=0
        self.root_moves=legal(self.pos);self.root_key=self.pos.identity()
    def legal(self,p,captures=False,poll=True):return legal(p,captures,self.check_time if poll else None)
    def check_time(self):
